export function render() {
  const data = [{"day":"Mon","celsius":18},{"day":"Tue","celsius":21},{"day":"Wed","celsius":19},{"day":"Thu","celsius":24}];

  const width = 800;
  const height = 500;
  const padding = 60;

  const days = data.map(d => d.day);
  const temps = data.map(d => d.celsius);
  const minTemp = Math.min(...temps);
  const maxTemp = Math.max(...temps);

  const xStep = (width - 2 * padding) / (data.length - 1);
  const yRange = maxTemp - minTemp;
  const yScale = (height - 2 * padding) / (yRange || 1);

  const points = data.map((d, i) => {
    const x = padding + i * xStep;
    const y = height - padding - (d.celsius - minTemp) * yScale;
    return { x, y, temp: d.celsius };
  });

  const pathData = points.map((p, i) => `${i === 0 ? 'M' : 'L'} ${p.x},${p.y}`).join(' ');

  const yTicks = 5;
  const yTickStep = yRange / (yTicks - 1) || 1;

  return `
    <svg width="${width}" height="${height}" xmlns="http://www.w3.org/2000/svg">
      <rect width="${width}" height="${height}" fill="#ffffff"/>

      <!-- Grid lines -->
      ${Array.from({length: yTicks}, (_, i) => {
        const temp = minTemp + i * yTickStep;
        const y = height - padding - i * yTickStep * yScale;
        return `<line x1="${padding}" y1="${y}" x2="${width - padding}" y2="${y}" stroke="#e0e0e0" stroke-width="1"/>`;
      }).join('')}

      <!-- Axes -->
      <line x1="${padding}" y1="${padding}" x2="${padding}" y2="${height - padding}" stroke="#333" stroke-width="2"/>
      <line x1="${padding}" y1="${height - padding}" x2="${width - padding}" y2="${height - padding}" stroke="#333" stroke-width="2"/>

      <!-- Y-axis labels -->
      ${Array.from({length: yTicks}, (_, i) => {
        const temp = Math.round(minTemp + i * yTickStep);
        const y = height - padding - i * yTickStep * yScale;
        return `<text x="${padding - 10}" y="${y + 5}" text-anchor="end" font-family="Arial" font-size="12" fill="#666">${temp}°C</text>`;
      }).join('')}

      <!-- X-axis labels -->
      ${points.map((p, i) => `
        <text x="${p.x}" y="${height - padding + 25}" text-anchor="middle" font-family="Arial" font-size="12" fill="#666">${days[i]}</text>
      `).join('')}

      <!-- Line -->
      <path d="${pathData}" fill="none" stroke="#3b82f6" stroke-width="3"/>

      <!-- Points -->
      ${points.map(p => `
        <circle cx="${p.x}" cy="${p.y}" r="5" fill="#3b82f6"/>
        <text x="${p.x}" y="${p.y - 12}" text-anchor="middle" font-family="Arial" font-size="11" fill="#333" font-weight="bold">${p.temp}°C</text>
      `).join('')}

      <!-- Title -->
      <text x="${width / 2}" y="30" text-anchor="middle" font-family="Arial" font-size="18" font-weight="bold" fill="#333">Daily High Temperature</text>
    </svg>
  `;
}

export const meta = {
  type: "line",
  values: [18, 21, 19, 24]
};
