export function render() {
  const data = [{"region":"North","sales":40},{"region":"South","sales":55},{"region":"East","sales":32},{"region":"West","sales":48}];

  const width = 800;
  const height = 500;
  const margin = { top: 40, right: 40, bottom: 60, left: 60 };
  const chartWidth = width - margin.left - margin.right;
  const chartHeight = height - margin.top - margin.bottom;

  const maxSales = Math.max(...data.map(d => d.sales));
  const yScale = maxSales * 1.1;
  const barWidth = chartWidth / data.length * 0.7;
  const barSpacing = chartWidth / data.length;

  const bars = data.map((d, i) => {
    const barHeight = (d.sales / yScale) * chartHeight;
    const x = margin.left + i * barSpacing + (barSpacing - barWidth) / 2;
    const y = margin.top + chartHeight - barHeight;

    return `
      <rect x="${x}" y="${y}" width="${barWidth}" height="${barHeight}" fill="rgba(54, 162, 235, 0.8)" stroke="rgba(54, 162, 235, 1)" stroke-width="1"/>
      <text x="${x + barWidth / 2}" y="${y - 5}" text-anchor="middle" font-size="14" fill="#666">${d.sales}</text>
      <text x="${x + barWidth / 2}" y="${margin.top + chartHeight + 25}" text-anchor="middle" font-size="14" fill="#666">${d.region}</text>
    `;
  }).join('');

  const yTicks = 5;
  const gridLines = Array.from({ length: yTicks + 1 }, (_, i) => {
    const value = Math.round((yScale / yTicks) * i);
    const y = margin.top + chartHeight - (i / yTicks) * chartHeight;

    return `
      <line x1="${margin.left}" y1="${y}" x2="${margin.left + chartWidth}" y2="${y}" stroke="#e0e0e0" stroke-width="1"/>
      <text x="${margin.left - 10}" y="${y + 4}" text-anchor="end" font-size="12" fill="#666">${value}</text>
    `;
  }).join('');

  return `
    <svg width="${width}" height="${height}" xmlns="http://www.w3.org/2000/svg">
      <rect width="${width}" height="${height}" fill="white"/>
      <text x="${width / 2}" y="${margin.top / 2 + 5}" text-anchor="middle" font-size="18" font-weight="bold" fill="#333">Sales by Region</text>
      ${gridLines}
      <line x1="${margin.left}" y1="${margin.top}" x2="${margin.left}" y2="${margin.top + chartHeight}" stroke="#333" stroke-width="2"/>
      <line x1="${margin.left}" y1="${margin.top + chartHeight}" x2="${margin.left + chartWidth}" y2="${margin.top + chartHeight}" stroke="#333" stroke-width="2"/>
      ${bars}
      <text x="${margin.left / 2}" y="${margin.top + chartHeight / 2}" text-anchor="middle" font-size="14" fill="#666" transform="rotate(-90, ${margin.left / 2}, ${margin.top + chartHeight / 2})">Sales</text>
      <text x="${margin.left + chartWidth / 2}" y="${height - 10}" text-anchor="middle" font-size="14" fill="#666">Region</text>
    </svg>
  `;
}

export const meta = {
  type: "bar",
  values: [{"region":"North","sales":40},{"region":"South","sales":55},{"region":"East","sales":32},{"region":"West","sales":48}]
};
