export function render() {
  const data = [
    { label: "Yes", value: 64 },
    { label: "No", value: 22 },
    { label: "Later", value: 14 }
  ];

  const COLORS = ['#0088FE', '#00C49F', '#FFBB28'];
  const total = data.reduce((sum, item) => sum + item.value, 0);

  const cx = 200;
  const cy = 200;
  const outerRadius = 120;
  const innerRadius = 70;

  let currentAngle = -90;

  const paths = data.map((item, index) => {
    const percentage = item.value / total;
    const angle = percentage * 360;
    const startAngle = currentAngle;
    const endAngle = currentAngle + angle;

    const startRad = (startAngle * Math.PI) / 180;
    const endRad = (endAngle * Math.PI) / 180;

    const x1 = cx + outerRadius * Math.cos(startRad);
    const y1 = cy + outerRadius * Math.sin(startRad);
    const x2 = cx + outerRadius * Math.cos(endRad);
    const y2 = cy + outerRadius * Math.sin(endRad);
    const x3 = cx + innerRadius * Math.cos(endRad);
    const y3 = cy + innerRadius * Math.sin(endRad);
    const x4 = cx + innerRadius * Math.cos(startRad);
    const y4 = cy + innerRadius * Math.sin(startRad);

    const largeArc = angle > 180 ? 1 : 0;

    const pathData = [
      `M ${x1} ${y1}`,
      `A ${outerRadius} ${outerRadius} 0 ${largeArc} 1 ${x2} ${y2}`,
      `L ${x3} ${y3}`,
      `A ${innerRadius} ${innerRadius} 0 ${largeArc} 0 ${x4} ${y4}`,
      'Z'
    ].join(' ');

    currentAngle = endAngle;

    const midAngle = (startAngle + endAngle) / 2;
    const labelRadius = outerRadius + 30;
    const labelX = cx + labelRadius * Math.cos((midAngle * Math.PI) / 180);
    const labelY = cy + labelRadius * Math.sin((midAngle * Math.PI) / 180);

    return { pathData, color: COLORS[index], label: item.label, value: item.value, labelX, labelY, percentage: (percentage * 100).toFixed(1) };
  });

  return `
    <svg width="500" height="450" xmlns="http://www.w3.org/2000/svg">
      <g>
        ${paths.map(p => `<path d="${p.pathData}" fill="${p.color}" stroke="#fff" stroke-width="2"/>`).join('')}
        ${paths.map(p => `
          <text x="${p.labelX}" y="${p.labelY}" text-anchor="middle" fill="#333" font-size="14" font-family="Arial, sans-serif">
            <tspan x="${p.labelX}" dy="0">${p.label}</tspan>
            <tspan x="${p.labelX}" dy="16">${p.percentage}%</tspan>
          </text>
        `).join('')}
      </g>
      <g transform="translate(50, 420)">
        ${paths.map((p, i) => `
          <rect x="${i * 100}" y="0" width="12" height="12" fill="${p.color}"/>
          <text x="${i * 100 + 18}" y="10" font-size="12" font-family="Arial, sans-serif" fill="#666">${p.label}</text>
        `).join('')}
      </g>
    </svg>
  `;
}

