export function render() {
  const data = [
    {"month":"Jan","free":40,"pro":20},
    {"month":"Feb","free":42,"pro":28},
    {"month":"Mar","free":39,"pro":35}
  ];

  const width = 800;
  const height = 500;
  const padding = { top: 40, right: 40, bottom: 60, left: 60 };
  const chartWidth = width - padding.left - padding.right;
  const chartHeight = height - padding.top - padding.bottom;

  const months = data.map(d => d.month);
  const maxTotal = Math.max(...data.map(d => d.free + d.pro));
  const yMax = Math.ceil(maxTotal / 10) * 10;

  const xScale = (index) => padding.left + (index * chartWidth / (months.length - 1));
  const yScale = (value) => padding.top + chartHeight - (value / yMax * chartHeight);

  // Calculate stacked values
  const freePoints = data.map((d, i) => ({ x: xScale(i), y: yScale(d.free) }));
  const proPoints = data.map((d, i) => ({ x: xScale(i), y: yScale(d.free + d.pro) }));

  // Create path for free area (from bottom)
  const freePath = [
    `M ${freePoints[0].x} ${padding.top + chartHeight}`,
    ...freePoints.map(p => `L ${p.x} ${p.y}`),
    `L ${freePoints[freePoints.length - 1].x} ${padding.top + chartHeight}`,
    'Z'
  ].join(' ');

  // Create path for pro area (from free line to top of stack)
  const proPath = [
    `M ${freePoints[0].x} ${freePoints[0].y}`,
    ...proPoints.map((p, i) => `L ${p.x} ${p.y}`),
    ...freePoints.slice().reverse().map(p => `L ${p.x} ${p.y}`),
    'Z'
  ].join(' ');

  // Y-axis labels
  const yTicks = 5;
  const yLabels = Array.from({ length: yTicks + 1 }, (_, i) => {
    const value = (yMax / yTicks) * i;
    const y = yScale(value);
    return `
      <line x1="${padding.left - 5}" y1="${y}" x2="${padding.left}" y2="${y}" stroke="#666" stroke-width="1"/>
      <text x="${padding.left - 10}" y="${y}" text-anchor="end" dominant-baseline="middle" font-size="12" fill="#666">${value}</text>
      <line x1="${padding.left}" y1="${y}" x2="${width - padding.right}" y2="${y}" stroke="#e0e0e0" stroke-width="1"/>
    `;
  }).join('');

  // X-axis labels
  const xLabels = months.map((month, i) => `
    <line x1="${xScale(i)}" y1="${padding.top + chartHeight}" x2="${xScale(i)}" y2="${padding.top + chartHeight + 5}" stroke="#666" stroke-width="1"/>
    <text x="${xScale(i)}" y="${padding.top + chartHeight + 20}" text-anchor="middle" font-size="12" fill="#666">${month}</text>
  `).join('');

  return `
    <svg width="${width}" height="${height}" xmlns="http://www.w3.org/2000/svg">
      <rect width="${width}" height="${height}" fill="white"/>

      <!-- Y-axis grid and labels -->
      ${yLabels}

      <!-- X-axis -->
      <line x1="${padding.left}" y1="${padding.top + chartHeight}" x2="${width - padding.right}" y2="${padding.top + chartHeight}" stroke="#666" stroke-width="2"/>

      <!-- Y-axis -->
      <line x1="${padding.left}" y1="${padding.top}" x2="${padding.left}" y2="${padding.top + chartHeight}" stroke="#666" stroke-width="2"/>

      <!-- X-axis labels -->
      ${xLabels}

      <!-- Stacked areas -->
      <path d="${freePath}" fill="rgba(54, 162, 235, 0.6)" stroke="rgb(54, 162, 235)" stroke-width="2"/>
      <path d="${proPath}" fill="rgba(255, 99, 132, 0.6)" stroke="rgb(255, 99, 132)" stroke-width="2"/>

      <!-- Title -->
      <text x="${width / 2}" y="20" text-anchor="middle" font-size="16" font-weight="bold" fill="#333">Subscribers by Plan</text>

      <!-- Legend -->
      <rect x="${width - padding.right - 120}" y="${padding.top + 10}" width="15" height="15" fill="rgba(255, 99, 132, 0.6)" stroke="rgb(255, 99, 132)"/>
      <text x="${width - padding.right - 100}" y="${padding.top + 22}" font-size="12" fill="#666">Pro</text>

      <rect x="${width - padding.right - 120}" y="${padding.top + 35}" width="15" height="15" fill="rgba(54, 162, 235, 0.6)" stroke="rgb(54, 162, 235)"/>
      <text x="${width - padding.right - 100}" y="${padding.top + 47}" font-size="12" fill="#666">Free</text>
    </svg>
  `;
}

