                grid: {
                  drawOnChartArea: false
                },
                ticks: {
                  callback: function(value) {
                    return (value * 100).toFixed(1) + '%';
                  }
                }
              }
            },
            plugins: {
              tooltip: {
                callbacks: {
                  label: function(context) {
                    let label = context.dataset.label || '';
                    if (label) {
