export function render() {
  const data = [
    {"hour":"9","day":"Mon","load":1},
    {"hour":"10","day":"Mon","load":5},
    {"hour":"9","day":"Tue","load":3}
  ];

  const days = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
  const hours = Array.from(new Set(data.map(d => d.hour))).sort((a, b) => Number(a) - Number(b));

  const heatmapData = data.map(item => {
    return [hours.indexOf(item.hour), days.indexOf(item.day), item.load];
  });

  const option = {
    tooltip: {
      position: 'top'
    },
    grid: {
      left: '10%',
      right: '10%',
      top: '10%',
      bottom: '15%'
