```javascript
export function render() {
  const data = [10, 12, 9, 14, 13];
  const width = 400;
  const height = 100;
  const padding = 10;

  const max = Math.max(...data);
  const min = Math.min(...data);
  const range = max - min || 1;

  const chartWidth = width - 2 * padding;
  const chartHeight = height - 2 * padding;

  const points = data.map((value, index) => {
    const x = padding + (index / (data.length - 1)) * chartWidth;
    const y = padding + chartHeight - ((value - min) / range) * chartHeight;
    return `${x},${y}`;
  }).join(' ');

  const firstPoint = `${padding},${height - padding}`;
  const lastPoint = `${width - padding},${height - padding}`;
  const areaPoints = `${firstPoint} ${points} ${lastPoint}`;

  return `
    <svg width="${width}" height="${height}" xmlns="http://www.w3.org/2000/svg">
      <defs>
        <linearGradient id="areaGradient" x1="0%" y1="0%" x2="0%" y2="100%">
          <stop offset="0%" style="stop-color:rgb(75,192,192);stop-opacity:0.4" />
          <stop offset="100%" style="stop-color:rgb(75,192,192);stop-opacity:0.1" />
        </linearGradient>
      </defs>
      <polygon points="${areaPoints}" fill="url(#areaGradient)" />
      <polyline points="${points}" fill="none" stroke="rgb(75,192,192)" stroke-width="2" />
    </svg>
  `;
}

